    case 8:if(SmokeTime>.6){SmokeCheck(FMath::Abs(FRotator::NormalizeAxis(P->GetActorRotation().Yaw-PC->GetControlRotation().Yaw))<1,TEXT("Outdoor arrival aligns body and camera direction"));SmokeCheck(FVector::Dist2D(PC->PlayerCameraManager->GetCameraLocation(),P->GetActorLocation())>150,TEXT("Door arrival leaves clearance for the following camera"));SmokeCheck(N->StreetRoute&&N->Route.Num()>2,TEXT("Park guide uses the actual connected street network"));SmokeCheck(N->Goal().Label==TEXT("Park")&&N->Guidance().Contains(TEXT("m direct")),TEXT("Outside guidance names destination and distance"));SmokeCheck(N->Location().Contains(TEXT("front garden")),TEXT("Location finder recognizes home front garden"));Shot(TEXT("NavigationOutside.png"));Next();}break;
